Then(/^the "Mark all as complete" checkbox is checked$/, function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'Expected toggle-all checkbox to exist');
  assert.ok(toggleAll.checked, 'Expected toggle-all checkbox to be checked');
