Then(/^the todo-count shows "([^"]+)"$/, function (text) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'Expected .todo-count element');
  assert.strictEqual(el.textContent.trim(), text, 'Expected todo-count to show "' + text + '"');
