  const data = JSON.parse(this.localStorage.getItem('todos-javascript'));
  assert.ok(Array.isArray(data), 'Expected todos in localStorage');
  const item = data.find(t => t.title === title);
  assert.ok(item, `Expected item "${title}" in localStorage`);
  assert.strictEqual(item.completed, true, `Expected "${title}" completed to be true`);
